WITH metrics AS (SELECT *, ROUND(units / SUM(units) OVER (PARTITION BY product_id), 4) units_share, ROUND(units / SUM(units) OVER (PARTITION BY store_id), 4) units_share_2 FROM store_sales) SELECT product_id, DATE_TRUNC('YEAR', sale_date) AS year_start, COUNT(DISTINCT store_id) AS distinct_store_ids, STDDEV_SAMP(units) AS units_stddev, RANK() OVER (PARTITION BY product_id ORDER BY COUNT(DISTINCT store_id) DESC) AS distinct_store_ids_rank FROM metrics GROUP BY product_id, DATE_TRUNC('YEAR', sale_date)
